import React, { useState, useEffect, useRef } from 'react';
import EnhancedDraggableWidget from '../EnhancedDraggableWidget';
import './SearchWidget.css';

const SearchWidget = ({ onClose, isVisible = true }) => {
  const [activeTab, setActiveTab] = useState('current'); // 'current' or 'history'
  const [searchContent, setSearchContent] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [searchHistory, setSearchHistory] = useState([]);
  const [widgetSize, setWidgetSize] = useState({ width: 550, height: 600 });
  const [isResizing, setIsResizing] = useState(false);
  const widgetRef = useRef(null);
  const resizeStartRef = useRef({ x: 0, y: 0, width: 0, height: 0 });

  // Initialize widget position and load history
  useEffect(() => {
    // Load search history from localStorage
    const savedHistory = localStorage.getItem('astra_search_history');
    if (savedHistory) {
      try {
        setSearchHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error('Error loading search history:', e);
        setSearchHistory([]);
      }
    }
  }, []);

  // Function to increase widget size
  const increaseWidgetSize = () => {
    setWidgetSize(prev => ({
      width: prev.width + 100,
      height: prev.height + 100
    }));
  };

  // Function to decrease widget size
  const decreaseWidgetSize = () => {
    setWidgetSize(prev => ({
      width: Math.max(400, prev.width - 100), // Minimum width of 400
      height: Math.max(500, prev.height - 100) // Minimum height of 500
    }));
  };

  // Function to switch tabs
  const switchTab = (tabName) => {
    setActiveTab(tabName);
  };

  // Function to view a history item
  const viewHistoryItem = (item) => {
    setSearchContent(item.result);
    setActiveTab('current');
  };

  // Function to clear search history
  const clearHistory = () => {
    setSearchHistory([]);
    localStorage.removeItem('astra_search_history');
  };

  // Function to copy search content to clipboard
  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(searchContent);
      // Optionally show a notification that text was copied
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  // Function to handle resize start
  const handleResizeStart = (e) => {
    e.preventDefault();
    setIsResizing(true);
    resizeStartRef.current = {
      x: e.clientX,
      y: e.clientY,
      width: widgetSize.width,
      height: widgetSize.height,
    };
  };

  // Function to update search content
  const updateSearchContent = async (text) => {
    setIsLoading(true);

    try {
      // Simulate processing time for visual feedback
      await new Promise(resolve => setTimeout(resolve, 300));

      setSearchContent(text);

      // Add to search history
      const newHistoryItem = {
        id: Date.now(),
        query: text.substring(0, 30) + (text.length > 30 ? '...' : ''), // Generate a title/summary
        result: text,
        timestamp: new Date().toLocaleString()
      };

      const updatedHistory = [newHistoryItem, ...searchHistory].slice(0, 50); // Keep last 50 searches
      setSearchHistory(updatedHistory);
      localStorage.setItem('astra_search_history', JSON.stringify(updatedHistory));
    } catch (error) {
      console.error('Error updating search content:', error);
      setSearchContent('Error displaying search results');
    } finally {
      setIsLoading(false);
    }
  };

  // Effect to handle resizing
  useEffect(() => {
    if (!isResizing) return;

    const handleMouseMove = (e) => {
      const deltaX = e.clientX - resizeStartRef.current.x;
      const deltaY = e.clientY - resizeStartRef.current.y;

      setWidgetSize({
        width: Math.max(400, resizeStartRef.current.width + deltaX),
        height: Math.max(500, resizeStartRef.current.height + deltaY)
      });
    };

    const handleMouseUp = () => {
      setIsResizing(false);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isResizing]);


  if (!isVisible) return null;

  return (
    <EnhancedDraggableWidget
      id="searchWidget"
      className="search-widget"
      title="NOVA SEARCH"
      initialSize={{ width: 550, height: 600 }}
      minSize={{ width: 400, height: 500 }}
      onClose={onClose}
      isVisible={isVisible}
    >
      <div className="corner-top-right"></div>
      <div className="corner-bottom-left"></div>
      <div className="widget-controls">
        <div className="widget-control-btn" onClick={increaseWidgetSize} title="Make Bigger">⧨</div>
        <div className="widget-control-btn" onClick={decreaseWidgetSize} title="Make Smaller">⧩</div>
        <div className="widget-control-btn" onClick={onClose} title="Close">⧬</div>
      </div>
      <div className="resize-handle" onMouseDown={handleResizeStart}></div>
      <div className="search-wrapper">
        {/* Header */}
        <div className="search-label">
          SEARCH
        </div>

        {/* Display Screen */}
        <div className="search-screen-area">
          {isLoading ? (
            <div className="search-loading show">Processing search...</div>
          ) : (
            <>
              <div className="search-content-text">{searchContent}</div>
              {searchContent && (
                <button className="copy-button" onClick={copyToClipboard} title="Copy search results">
                  <i className="fas fa-copy"></i>
                </button>
              )}
            </>
          )}
        </div>

        {/* Tab Controls */}
        <div className="controls-section">
          <div className="search-tabs">
            <button
              className={`tab-button ${activeTab === 'current' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); switchTab('current'); }}
            >
              Current
            </button>
            <button
              className={`tab-button ${activeTab === 'history' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); switchTab('history'); }}
            >
              History
            </button>
          </div>
        </div>

        {/* Content Area */}
        <div className="button-section">
          {activeTab === 'current' ? (
            <div className="search-current-view">
              {searchContent ? (
                <div className="search-content">
                  {searchContent}
                </div>
              ) : (
                <div className="search-placeholder">
                  Enter a search query to see results here.
                </div>
              )}
            </div>
          ) : (
            <div className="search-history-view">
              {searchHistory.length > 0 ? (
                <>
                  <div className="search-history-controls" style={{ marginBottom: '10px', textAlign: 'right' }}>
                    <button
                      className="search-clear-history-btn"
                      onClick={clearHistory}
                      style={{
                        background: 'linear-gradient(135deg, rgba(255, 80, 80, 0.9) 0%, rgba(255, 50, 50, 0.9) 100%)',
                        border: '1px solid rgba(255, 30, 30, 0.7)',
                        color: 'white',
                        padding: '4px 8px',
                        borderRadius: '4px',
                        fontSize: '10px',
                        cursor: 'pointer'
                      }}
                    >
                      Clear History
                    </button>
                  </div>
                  <div className="search-history">
                    {searchHistory.map(item => (
                      <div
                        key={item.id}
                        className="search-history-item"
                        onClick={() => viewHistoryItem(item)}
                      >
                        <div className="search-history-query">{item.query}</div>
                        <div className="search-history-date">{item.timestamp}</div>
                        <div className="search-history-preview">
                          {item.result.length > 100 ? item.result.substring(0, 100) + '...' : item.result}
                        </div>
                      </div>
                    ))}
                  </div>
                </>
              ) : (
                <div className="search-history-empty">
                  No search history yet
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </EnhancedDraggableWidget>
  );
};

export default SearchWidget;
